"use strict";(globalThis.webpackChunkportfolio=globalThis.webpackChunkportfolio||[]).push([[2081],{1988(e,t,n){n.r(t),n.d(t,{assets:()=>h,contentTitle:()=>s,default:()=>u,frontMatter:()=>r,metadata:()=>o,toc:()=>l});var o=n(6838),i=n(4848),a=n(8453);const r={slug:"writing-for-the-engineer-who-will-replace-you",title:"Writing for the Engineer Who Will Replace You",authors:"Faith Wachukwu",tags:["devops","docs"]},s=void 0,h={authorsImageUrls:[void 0]},l=[{value:"You&#39;re Not Writing for Your Team",id:"youre-not-writing-for-your-team",level:2},{value:"The &quot;Why&quot; Matters",id:"the-why-matters",level:2},{value:"Write for the 2 AM Version of That Person",id:"write-for-the-2-am-version-of-that-person",level:2},{value:"Treat Documentation Like a Product",id:"treat-documentation-like-a-product",level:2},{value:"What To Do Differently",id:"what-to-do-differently",level:2},{value:"Conclusion",id:"conclusion",level:2}];function d(e){const t={em:"em",h2:"h2",li:"li",p:"p",ul:"ul",...(0,a.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)("img",{src:"/img/blog/cover-writing-engineer.jpg",alt:"An engineer working in the dark."}),"\n",(0,i.jsx)(t.p,{children:"You\u2019re staring at internal documentation at 11 PM, trying to figure out why a deployment pipeline is failing, but it's incomplete. It looks like whoever wrote it stopped midway, like they got pulled into a meeting and never came back. Well, what matters now is that you\u2019re stuck."}),"\n",(0,i.jsx)(t.p,{children:"As someone who has been in this situation, you should think differently when writing documentation about who you\u2019re writing for and how they would feel with incomplete docs. In this post, you\u2019ll learn how to approach documentation as an engineer."}),"\n",(0,i.jsx)(t.h2,{id:"youre-not-writing-for-your-team",children:"You're Not Writing for Your Team"}),"\n",(0,i.jsx)(t.p,{children:"When starting a new role or in your current role, you might think your colleagues might not need your docs. And yes, that\u2019s right, they might not. I mean, they were in the same Slack threads and meetings. They were there when someone made a questionable decision on the infrastructure on a Friday."}),"\n",(0,i.jsx)(t.p,{children:"Your real audience is the person who is employed 18 months later, handed the workload and is told, \u201cYou own this now.\u201d With no context, no Slack history, and no memory of what has happened previously that shaped how the systems work today. All they have is what was left behind."}),"\n",(0,i.jsx)(t.h2,{id:"the-why-matters",children:'The "Why" Matters'}),"\n",(0,i.jsx)(t.p,{children:"Initially, at the start of my career in DevOps, I would document things I did by writing things clearly. Well, it became useless six months down the line when the steps had changed. I didn\u2019t go back to update the document."}),"\n",(0,i.jsx)(t.p,{children:"Knowing the reason why decisions were made is important in documentation. Beyond writing out the steps of actions taken, you should know the context behind decisions to understand the why, instead of following what you don\u2019t understand. This could be as simple as two sentences, not like a full-blown write-up, and it can save someone the time and financial cost due to a mistake."}),"\n",(0,i.jsx)(t.h2,{id:"write-for-the-2-am-version-of-that-person",children:"Write for the 2 AM Version of That Person"}),"\n",(0,i.jsx)(t.p,{children:"When you\u2019re on call, you know there is a difference between reading documentation to find out how a tool works versus reading it when there is downtime, and you are getting pinged nonstop. At that moment, you\u2019re a different reader. One who is not interested in how it was written, you just want answers fast. You\u2019d want to know:"}),"\n",(0,i.jsxs)(t.ul,{children:["\n",(0,i.jsx)(t.li,{children:"what does this service depend on?"}),"\n",(0,i.jsx)(t.li,{children:"what breaks when it goes down?"}),"\n",(0,i.jsx)(t.li,{children:"how do I restart it without making it worse?"}),"\n"]}),"\n",(0,i.jsx)(t.p,{children:"So when you\u2019re structuring anything operational, keep that person in mind. Make sure you use short sentences, clear headings, and remove what would create doubt in their minds. If there\u2019s a command they\u2019ll need to run, include it, make it visible and easy to find and not buried deep into a paragraph section."}),"\n",(0,i.jsx)(t.h2,{id:"treat-documentation-like-a-product",children:"Treat Documentation Like a Product"}),"\n",(0,i.jsx)(t.p,{children:"Treating your documentation as a product, not a side work, is a shift you should make. Think about it this way: if the person replacing you can\u2019t understand the system from your documentation, then you haven\u2019t finished working on that documentation."}),"\n",(0,i.jsx)(t.p,{children:"When you see documentation as a product that has users, a purpose, and a quality standard to follow, you start making different choices. You\u2019ll think about the structure, what is important to add or leave out, and how to maintain it."}),"\n",(0,i.jsxs)("div",{style:{textAlign:"center"},children:[(0,i.jsx)("img",{src:"/img/blog/writingEngineer2.png",alt:"A simple flowchart showing Documentation-Users-Feedback-Improvements."}),(0,i.jsx)(t.p,{children:(0,i.jsx)(t.em,{children:"A simple workflow diagram of documentation lifecycle"})})]}),"\n",(0,i.jsx)(t.h2,{id:"what-to-do-differently",children:"What To Do Differently"}),"\n",(0,i.jsx)(t.p,{children:"With the mindset of seeing documentation as a product, you\u2019d document the state of things for every system you own. Mention what works well, what\u2019s been held together by strings, and if there are potential risks in the systems."}),"\n",(0,i.jsx)(t.p,{children:"If you had to dig through 3 Jira tickets and a Slack thread to figure something out that is needed, then it\u2019s a sign you should document it. The fact that it was hard to find means someone will face the same issue. It\u2019s easier to revisit docs than to dig through Slack threads."}),"\n",(0,i.jsx)(t.p,{children:"In cases where there were recent additions or something was confusing in a runbook you own, correct it right then and not later. That\u2019s because the next person who\u2019ll read it won\u2019t have context to know there is a problem. They\u2019ll trust it blindly."}),"\n",(0,i.jsx)(t.p,{children:"Additionally, write like a human. Use \u201cwe\u201d and \u201cyou\u201d occasionally. When something is genuinely confusing, you\u2019d say, \u201cThis is confusing, but here\u2019s the deal\u201d. Don\u2019t pretend everything works perfectly when it doesn\u2019t. Writing honestly in documentation helps to build trust, even with someone you\u2019ll never meet."}),"\n",(0,i.jsx)(t.h2,{id:"conclusion",children:"Conclusion"}),"\n",(0,i.jsx)(t.p,{children:"At the end, everything you\u2019ll build, configure, or every shortcut you\u2019ll take to implement things will be inherited by someone else. The quality of the documentation you leave behind says something about you as a professional."}),"\n",(0,i.jsx)(t.p,{children:"Leave brilliant documentation handoffs to the next person. Brilliant, not in the sense of perfect documentation, but documentation that is written with the next person in mind. Let it be written clearly with the necessary information. This leaves a trail that says, \u201cI cared about whoever came after me.\u201d"})]})}function u(e={}){const{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(d,{...e})}):d(e)}},8453(e,t,n){n.d(t,{R:()=>r,x:()=>s});var o=n(6540);const i={},a=o.createContext(i);function r(e){const t=o.useContext(a);return o.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function s(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:r(e.components),o.createElement(a.Provider,{value:t},e.children)}},6838(e){e.exports=JSON.parse('{"permalink":"/blog/writing-for-the-engineer-who-will-replace-you","source":"@site/blog/2026-03-09-writing-for-the-engineer-who-will-replace-you.md","title":"Writing for the Engineer Who Will Replace You","description":"You\u2019re staring at internal documentation at 11 PM, trying to figure out why a deployment pipeline is failing, but it\'s incomplete. It looks like whoever wrote it stopped midway, like they got pulled into a meeting and never came back. Well, what matters now is that you\u2019re stuck.","date":"2026-03-09T00:00:00.000Z","tags":[{"inline":true,"label":"devops","permalink":"/blog/tags/devops"},{"inline":true,"label":"docs","permalink":"/blog/tags/docs"}],"readingTime":4.26,"hasTruncateMarker":true,"authors":[{"name":"Faith Wachukwu","title":"Documentation Engineer","url":"https://faithkovi.xyz","socials":{"linkedin":"https://www.linkedin.com/in/faith-kovi/"},"imageURL":"/img/profile.jpg","key":"Faith Wachukwu","page":null}],"frontMatter":{"slug":"writing-for-the-engineer-who-will-replace-you","title":"Writing for the Engineer Who Will Replace You","authors":"Faith Wachukwu","tags":["devops","docs"]},"unlisted":false,"prevItem":{"title":"How to Write Documentation for Both Humans and AI Retrieval Systems","permalink":"/blog/how-to-write-documentation-for-both-humans-and-ai-retrieval-systems"},"nextItem":{"title":"What Makes API Documentation Work?","permalink":"/blog/what-makes-api-documentation-work"}}')}}]);